def hidden_rule_fn(state):
    strip = state[0]
    n = len(strip)
    next_strip = []
    for i in range(n):
        # Compute range-hexad (neighbors at offsets -3, -2, -1, +1, +2, +3)
        neighbors = []
        for offset in [-3, -2, -1, 1, 2, 3]:
            idx = (i + offset) % n
            neighbors.append(strip[idx])

        s = sum(neighbors) % 3
        ck = neighbors.count(0)
        cs = neighbors.count(1)
        cd = neighbors.count(2)

        # Determine majority (priority: cd > cs > ck)
        if cd >= cs and cd >= ck:
            majority = 'cd'
        elif cs >= ck:
            majority = 'cs'
        else:
            majority = 'ck'

        state_i = strip[i]

        if s == 0:
            if state_i == 0:
                next_val = 0
            elif state_i == 1:
                next_val = 1 if ck == cd else 2
            else:  # state_i == 2
                next_val = 1 if cs >= ck and cs >= cd else 0
        elif s == 1:
            if majority == 'cs':
                next_val = 2 if state_i != 0 else 1
            elif majority == 'ck':
                next_val = 2 if state_i == 2 else 1
            else:  # majority == 'cd'
                next_val = 0
        else:  # s == 2
            if majority == 'ck':
                next_val = cd if cd > 0 else (2 - state_i)
            elif majority == 'cd':
                next_val = state_i
            else:  # majority == 'cs'
                if state_i == 0:
                    next_val = 2
                elif state_i == 1:
                    next_val = 1 if ck < cd else 2
                else:  # state_i == 2
                    next_val = 0

        next_strip.append(next_val)

    return [next_strip]
